export class HTTPResponse {
  #headers?: Headers;
  #init?: Pick<ResponseInit, "status" | "statusText" | "headers"> | undefined;
  body?: BodyInit | null;
  constructor(
    body: BodyInit | null,
    init?: Pick<ResponseInit, "status" | "statusText" | "headers">,
  ) {
    this.body = body;
    this.#init = init;
  }
